func debug_ls(path: String) -> String:
	var d := DirAccess.open(path)
	if d == null:
		return "NO_DIR"
	return str(d.get_files()) + " | dirs: " + str(d.get_directories())


func debug_copy_dir(src: String, dst: String) -> int:
	var count := 0
	var d := DirAccess.open(src)
	if d == null:
		return -1
	DirAccess.make_dir_recursive_absolute(dst)
	for f in d.get_files():
		var out := FileAccess.open(dst.path_join(f), FileAccess.WRITE)
		if out:
			out.store_buffer(FileAccess.get_file_as_bytes(src.path_join(f)))
			out.close()
			count += 1
	for sub in d.get_directories():
		count += debug_copy_dir(src.path_join(sub), dst.path_join(sub))
	return count


